<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { Menu, X, Scale, ShieldCheck, Clock3, Award, FileText, Landmark, Handshake, ScrollText, ArrowRight, ChevronLeft, ChevronRight, LayoutDashboard, PanelTop, BriefcaseBusiness, Users, Newspaper, Settings, LogOut, Plus, Pencil, Trash2, Quote, Star, Sparkles, Phone, MapPin, MoveDown } from 'lucide-vue-next'
import heroDefault from './assets/hero-notary.png'
import heroNotaris from './assets/hero-team.jpg'
import heroSlideTwo from './assets/hero-slide-two.jpg'
import aboutTeam from './assets/about-team.jpg'
import teamRina from './assets/team-rina.webp'
import teamDewi from './assets/team-dewi.webp'
import teamHijab from './assets/team-hijab.webp'
import teamWoman from './assets/team-woman.webp'
import teamBudi from './assets/team-budi.webp'
import teamAndika from './assets/team-andika.webp'
import teamSalfa from './assets/team-salfa.jpg'
import logoOza from './assets/logo-oza.webp'
import consultationChat from './assets/iconchat.png'

type Service = { title: string; description: string; icon: typeof FileText }
const mobileOpen = ref(false), admin = ref(false), adminMenu = ref('Dashboard'), activeSlide = ref(0), scrollY = ref(0)
const hero = computed(() => activeSlide.value === 2 ? heroNotaris : activeSlide.value === 1 ? heroSlideTwo : heroDefault)
const slides = ref([
  { eyebrow: 'LEGALITAS TERJAGA', title: 'Setiap dokumen,', middle: 'setiap keputusan,', accent: 'ditangani dengan pasti.', copy: 'Pendampingan legal yang transparan untuk pribadi, keluarga, dan bisnis Anda.' },
  { eyebrow: 'MITRA STRATEGIS ANDA', title: 'Dari konsultasi', middle: 'hingga akta', accent: 'selesai dengan tenang.', copy: 'Proses yang jelas, komunikasi yang nyaman, dan pelayanan yang tepat waktu.' },
  { eyebrow: 'KANTOR NOTARIS & PPAT', title: 'Kepastian Hukum,', middle: 'Kepercayaan Anda,', accent: 'Komitmen Kami.', copy: 'Kami memberikan layanan notaris yang profesional, akurat, dan terpercaya untuk setiap kebutuhan hukum Anda.' }
])
const testimonials = ref([
  { quote: 'Proses pengurusan akta sangat jelas dan cepat. Timnya memberi penjelasan yang membuat kami merasa tenang.', name: 'Ferry Gunawan', role: 'Direktur Utama, Prima Karya' },
  { quote: 'Sangat profesional sejak konsultasi pertama. Semua dokumen usaha kami ditangani dengan rapi dan tepat waktu.', name: 'Nadia Putri', role: 'Founder, Atelier Nusa' },
  { quote: 'Komunikatif, teliti, dan transparan. Kami mendapatkan solusi yang paling sesuai untuk kebutuhan keluarga.', name: 'Hendra Wijaya', role: 'Klien Pribadi' }
])
const activeTestimonial = ref(0)
const visibleTestimonials = computed(() => Array.from({ length: testimonials.value.length }, (_, index) => testimonials.value[(activeTestimonial.value + index) % testimonials.value.length]))
const teamMembers = ref([
  { name: 'Salfa Novia Roza, S.H., M.Kn.', role: 'Notaris & PPAT\nNPAK · Notaris Pasar Modal Terdaftar OJK', photo: teamSalfa },
  { name: 'Fairy lorenza', role: 'Notarial & PPAT Associate', photo: teamHijab },
  { name: 'Lolonta Gabriella Exaudita Ujung, S.H., M.Kn', role: 'Notarial Associate', photo: teamDewi },
  { name: 'Nauval Musthofa, S.H', role: 'Notarial & Field Operations', photo: teamAndika },
  { name: 'Gabriellia Tefany', role: 'Notarial & PPAT Associate', photo: teamRina },
  { name: 'Hidayatul Mithri Zura S.H., M.Kn.', role: 'Notarial Intern', photo: teamWoman },
  { name: 'Muhammad Khadafy', role: 'Office Support', photo: teamBudi }
])
const articles = ref([
  { title: 'Pentingnya Akta Autentik untuk Perjanjian', tag: 'EDUKASI HUKUM', copy: 'Informasi ringkas untuk membantu Anda membuat keputusan yang tepat.' },
  { title: 'Langkah Awal Mendirikan Perseroan Terbatas', tag: 'EDUKASI HUKUM', copy: 'Informasi ringkas untuk membantu Anda membuat keputusan yang tepat.' },
  { title: 'Memahami Legalitas dalam Transaksi Properti', tag: 'EDUKASI HUKUM', copy: 'Informasi ringkas untuk membantu Anda membuat keputusan yang tepat.' }
])
const site = ref({ brand: 'Notaris, PPAT, NPAK, & Notaris Pasar Modal Jakarta Selatan', footer: '© 2026 Salfa Novia Roza, S.H., M.Kn. Seluruh hak dilindungi.', googleReviews: { rating: '4,9', count: 37, url: 'https://www.google.com/search?q=salfanoviaroza+notaris' }, about: { title: 'Lebih dari Sekadar Akta.\nKami Hadir untuk Memberikan Kepastian.', paragraphs: ['Berawal dari Belitung Timur pada tahun 2020, kami terus berkembang dan sejak tahun 2025 hadir di Jakarta Selatan untuk memberikan pelayanan hukum yang profesional dan terpercaya.', 'Kami menyediakan layanan Notaris, PPAT, NPAK, dan Notaris Pasar Modal, dengan cakupan kebutuhan hukum bagi perorangan, keluarga, badan usaha, koperasi, transaksi pertanahan, hingga kebutuhan korporasi dan pasar modal.', 'Dalam setiap pekerjaan, kami mengutamakan integritas, ketelitian, profesionalisme, dan kerahasiaan. Setiap akta dan dokumen kami proses dengan cermat untuk memberikan kepastian hukum dan perlindungan bagi para pihak.', 'Karena bagi kami, sebuah akta bukan hanya tentang dokumen; melainkan tentang kepercayaan yang dipercayakan kepada kami.'], stats: [{ value: '6+', label: 'Tahun pengalaman' }, { value: '2.500+', label: 'Klien ditangani' }, { value: '3.000+', label: 'Akta diselesaikan' }] }, contact: { heading: 'Butuh Konsultasi Notaris/PPAT?', office: 'Alamat Kantor Notaris, PPAT, NPAK, & Notaris Pasar Modal Jakarta Selatan', name: 'Salfa Novia Roza, S.H., M.Kn.', address: 'Jl. KH. Ahmad Dahlan Kby. No.10 D, RT.1/RW.1, Kramat Pela, Kec. Kby. Baru, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12130', maps: 'https://maps.app.goo.gl/VD6PphJXQaMMVmD1A?g_st=iw', whatsapp: '6282241145758', message: 'Halo Saya dari website https://salfanoviaroza.com/ ingin konsultasi.' } })
const waLink = computed(() => `https://wa.me/${site.value.contact.whatsapp}?text=${encodeURIComponent(site.value.contact.message)}`)
const services = ref<Service[]>([
  { title: 'Pembuatan Akta', description: 'Pembuatan akta autentik sesuai peraturan yang berlaku.', icon: FileText },
  { title: 'Pengesahan Dokumen', description: 'Legalisasi dokumen untuk keperluan pribadi maupun perusahaan.', icon: ShieldCheck },
  { title: 'Perjanjian & Kontrak', description: 'Pembuatan perjanjian yang mengikat dan melindungi kepentingan Anda.', icon: Handshake },
  { title: 'Wasiat & Hibah', description: 'Pembuatan surat wasiat, hibah, dan dokumen waris lainnya.', icon: ScrollText },
  { title: 'Pendirian PT', description: 'Pendampingan lengkap sejak akta hingga legalitas usaha.', icon: Landmark },
  { title: 'Konsultasi Hukum', description: 'Diskusi awal yang jelas untuk kebutuhan legal Anda.', icon: Scale }
])
const stats = computed(() => [{label:'Slider',value:5},{label:'Layanan',value:services.value.length},{label:'Tim',value:4},{label:'Artikel',value:12}])
const nav = ['Beranda','Tentang','Layanan','Tim','Artikel','Galeri','Kontak']
function go(id:string){ document.getElementById(id.toLowerCase())?.scrollIntoView({behavior:'smooth'}); mobileOpen.value=false }
function addService(){ services.value.push({title:'Layanan Baru',description:'Deskripsi layanan dapat dikelola dari dashboard.',icon:Scale}) }
function removeService(i:number){ services.value.splice(i,1) }
function nextSlide(direction = 1){ activeSlide.value = (activeSlide.value + direction + slides.value.length) % slides.value.length }
let slider: number | undefined
let testimonialSlider: number | undefined
onMounted(async () => { slider = window.setInterval(() => nextSlide(), 10000); testimonialSlider = window.setInterval(() => activeTestimonial.value = (activeTestimonial.value + 1) % testimonials.value.length, 6500); window.addEventListener('scroll', () => scrollY.value = window.scrollY, {passive:true}); try { const response = await fetch('/api/site-content'); const saved = await response.json(); if (saved.brand) site.value.brand = saved.brand; if (saved.footer) site.value.footer = saved.footer; if (saved.googleReviews) site.value.googleReviews = saved.googleReviews; if (saved.about) site.value.about = saved.about; if (saved.contact) site.value.contact = saved.contact; if (saved.slides?.length) slides.value = saved.slides; if (saved.articles?.length) articles.value = saved.articles; if (saved.testimonials?.length) testimonials.value = saved.testimonials; if (saved.team?.length) teamMembers.value = saved.team.map((person:any, index:number) => ({ ...teamMembers.value[index % teamMembers.value.length], ...person })); if (saved.services?.length) services.value = saved.services.map((service:any, index:number) => ({ ...service, icon: services.value[index % services.value.length].icon })); } catch {} })
onUnmounted(() => { if (slider) window.clearInterval(slider); if (testimonialSlider) window.clearInterval(testimonialSlider) })
</script>

