    <div v-if="mobileOpen" class="drawer"><button class="close" @click="mobileOpen=false"><X/></button><button v-for="n in nav" :key="n" @click="go(n)">{{n}}</button><button class="button" @click="go('kontak')">Hubungi Kami</button></div>
    <main>
      <section id="beranda" class="hero" :class="{ 'hero-team': activeSlide === 2, 'hero-slide-two': activeSlide === 1 }" :style="{ backgroundImage: `${activeSlide === 2 ? 'linear-gradient(180deg, rgba(7,7,7,.08) 0%, rgba(7,7,7,.38) 100%)' : 'linear-gradient(90deg, rgba(7,7,7,.96) 0%, rgba(7,7,7,.79) 41%, rgba(7,7,7,.2) 100%)'}, url(${hero})` }"><div class="hero-grain"></div><transition name="slide-copy" mode="out-in"><div :key="activeSlide" class="hero-copy"><img v-if="activeSlide === 0" class="hero-slide-logo" :src="logoOza" alt="Logo Salffa Novia Roza"/><p class="eyebrow"><Sparkles :size="13"/>{{ slides[activeSlide].eyebrow }}</p><h1>{{slides[activeSlide].title}}<br>{{slides[activeSlide].middle}}<br><em>{{slides[activeSlide].accent}}</em></h1><p class="lead">{{slides[activeSlide].copy}}</p><div class="hero-actions"><button class="button" @click="go('kontak')">Konsultasi Sekarang <ArrowRight :size="16"/></button><button class="play-button" @click="go('tentang')"><span>01</span> Kenali Kami</button></div></div></transition><div class="hero-arrows"><button aria-label="Slide sebelumnya" @click="nextSlide(-1)"><ChevronLeft/></button><button aria-label="Slide berikutnya" @click="nextSlide()"><ChevronRight/></button></div><div class="hero-status"><span v-for="(_, index) in slides" :key="index" :class="{selected:index===activeSlide}" @click="activeSlide=index"></span><small>0{{ activeSlide + 1 }} / 0{{ slides.length }}</small></div><button class="scroll-hint" @click="go('layanan')"><MoveDown :size="17"/> Jelajahi layanan</button></section>
      <section class="trust"><article><Award/><div><b>Profesional</b><span>Layanan notaris oleh pejabat berwenang</span></div></article><article><ShieldCheck/><div><b>Terpercaya</b><span>Menjaga kerahasiaan dokumen</span></div></article><article><Clock3/><div><b>Cepat & Akurat</b><span>Proses tepat waktu dan sesuai hukum</span></div></article><article><Scale/><div><b>Berpengalaman</b><span>Pendampingan hukum berkualitas</span></div></article></section>
      <section id="layanan" class="section"><p class="eyebrow">LAYANAN PROFESIONAL</p><h2>Layanan Kami</h2><p class="section-intro">Solusi hukum yang terukur untuk kebutuhan personal dan bisnis.</p><div class="grid services"><article v-for="service in services" :key="service.title" class="card"><component :is="service.icon" class="gold"/><h3>{{service.title}}</h3><p>{{service.description}}</p><a href="#kontak" @click.prevent="go('kontak')">Pelajari lebih lanjut <ArrowRight :size="15"/></a></article></div></section>
      <section id="tentang" class="section split"><div class="about-visual"><img class="about-team-image" :src="aboutTeam" alt="Tim kantor notaris"/><div class="floating-chip"><ShieldCheck :size="17"/><span><b>Terverifikasi</b>Standar layanan profesional</span></div></div><div><p class="eyebrow">TENTANG KAMI</p><h2 class="about-title">{{ site.about.title }}</h2><div class="about-copy"><p v-for="paragraph in site.about.paragraphs" :key="paragraph">{{ paragraph }}</p></div><div class="number-grid"><div v-for="stat in site.about.stats" :key="stat.label"><b>{{ stat.value }}</b><span>{{ stat.label }}</span></div></div></div></section>
      <section id="tim" class="section"><div class="team-heading"><div><p class="eyebrow">ORANG DI BALIK KEPERCAYAAN</p><h2>Tim Kami</h2></div></div><div class="grid team team-all"><article v-for="person in teamMembers" :key="person.photo" class="card person"><div class="portrait"><img :src="person.photo" :alt="person.name"/></div><h3>{{person.name}}</h3><p>{{person.role}}</p></article></div></section>
      <section id="artikel" class="section"><p class="eyebrow">WAWASAN HUKUM</p><h2>Artikel Terbaru</h2><div class="grid articles"><article v-for="article in articles" :key="article.title" class="card"><span class="tag">{{ article.tag }}</span><h3>{{article.title}}</h3><p>{{ article.copy }}</p><a href="#kontak" @click.prevent="go('kontak')">Baca artikel <ArrowRight :size="15"/></a></article></div></section>
      <section class="testimonial-section"><div class="testimonial-orb"></div><p class="eyebrow">DIPERCAYA OLEH KLIEN</p><a class="google-reviews-summary" :href="site.googleReviews.url" target="_blank" rel="noopener noreferrer" aria-label="Lihat seluruh ulasan di Google"><b>{{ site.googleReviews.rating }}</b><span class="stars"><Star v-for="n in 5" :key="n" :size="16" fill="currentColor"/></span><span>{{ site.googleReviews.count }} ulasan di Google</span><ArrowRight :size="16"/></a><div class="testimonial-shell"><div class="testimonial-cards"><article v-for="person in visibleTestimonials" :key="person.name" class="testimonial-card"><Quote class="quote-mark"/><div class="stars"><Star v-for="n in 5" :key="n" :size="15" fill="currentColor"/></div><blockquote>“{{ person.quote }}”</blockquote><div class="client"><div>{{person.name[0]}}</div><span><b>{{person.name}}</b>{{person.role}}</span></div></article></div><div class="testimonial-controls"><button v-for="(_, index) in testimonials" :key="index" :class="{selected:index===activeTestimonial}" @click="activeTestimonial=index">0{{ index + 1 }}</button></div></div></section>
      <section id="kontak" class="contact"><div><p class="eyebrow">KONSULTASI AWAL</p><h2>{{ site.contact.heading }}</h2><p>{{ site.contact.office }}<br/>{{ site.contact.name }}</p><div class="contact-meta"><a :href="site.contact.maps" target="_blank" rel="noopener noreferrer"><MapPin :size="14"/>{{ site.contact.address }}</a></div></div><div class="contact-actions"><a class="button" :href="waLink" target="_blank" rel="noopener noreferrer">WhatsApp Kami</a></div></section>
    </main><a class="floating-consultation" :href="waLink" target="_blank" rel="noopener noreferrer" aria-label="Konsultasi melalui WhatsApp"><img :src="consultationChat" alt="Konsultasi Sekarang"/></a><footer><button class="brand"><Scale :size="22"/><span>{{ site.brand }}</span></button><span>{{ site.footer }}</span></footer>
  </div>
  <div v-else class="admin-shell"><aside><button class="brand" @click="admin=false"><Scale/><span>NOTARIS</span></button><button v-for="item in ['Dashboard','Slider','Tentang','Layanan','Tim','Artikel','Galeri','Pengaturan']" :key="item" :class="{active:adminMenu===item}" @click="adminMenu=item"><component :is="item==='Dashboard'?LayoutDashboard:item==='Slider'?PanelTop:item==='Layanan'?BriefcaseBusiness:item==='Tim'?Users:item==='Artikel'?Newspaper:Settings" :size="17"/>{{item}}</button><button class="logout" @click="admin=false"><LogOut :size="17"/>Keluar</button></aside><main class="dashboard"><header><div><p class="eyebrow">ADMINISTRASI</p><h2>{{adminMenu}}</h2></div><button class="button small" @click="addService"><Plus :size="16"/>Tambah Konten</button></header><div class="admin-stats"><article v-for="stat in stats" :key="stat.label"><span>{{stat.label}}</span><b>{{stat.value}}</b><i>Konten aktif</i></article></div><section class="admin-content"><div class="panel"><h3>{{adminMenu==='Layanan'?'Kelola Layanan':'Aktivitas Terbaru'}}</h3><template v-if="adminMenu==='Layanan'"><div v-for="(service,i) in services" :key="service.title+i" class="row"><component :is="service.icon" class="gold" :size="19"/><div><b>{{service.title}}</b><span>{{service.description}}</span></div><button aria-label="Edit"><Pencil :size="16"/></button><button aria-label="Hapus" class="danger" @click="removeService(i)"><Trash2 :size="16"/></button></div></template><template v-else><div v-for="text in ['Slider “Kepastian Hukum” diperbarui','Artikel baru siap diterbitkan','Pengaturan kontak diperbarui','Layanan Pembuatan Akta ditinjau']" :key="text" class="activity"><span></span><div><b>{{text}}</b><small>Hari ini, beberapa menit lalu</small></div></div></template></div><div class="panel chart"><h3>Statistik Pengunjung</h3><div class="bars"><i v-for="n in [25,48,35,60,46,78,89,65,95,80,100,92]" :key="n" :style="{height:n+'%'}"></i></div><p>Ringkasan kunjungan 30 hari terakhir.</p></div></section></main></div>
</template>
